// Pure decisions: this module cannot access the engine state or game RNG.
(function(){
 const axes=['strength','poison','block','exhaust'],names={strength:'筋力',poison:'毒',block:'ブロック',exhaust:'除外'};
 const config={version:'stages2-5-v1',keys:{strength:[19,20,21],poison:[16,17,18],block:[37,54,63],exhaust:[22,24,73]},completion:{keys:2,share:.45},weights:{axis:3,key:6,efficiency:1,role:3},ambiguityGap:1,time:{turn:8,card:3,battle:15},deckSize:14};
 function tags(c){let f=c.fx||{},a=[];if(f.s||f.doubleStr||f.strScale||f.strengthBlock||f.forge||f.exhaustStrength)a.push('strength');if(f.p||f.equalPoison||f.totalPoison||f.poisonDouble||f.poisonDraw)a.push('poison');if(f.b||f.agility||f.plate||f.exactBlock||f.blockScale||f.retainBlock||f.burn||f.thorns||f.thornGarden||f.thornShield||f.rage||f.nextBlock||f.passion||f.exhaustBlock)a.push('block');if(f.ex||f.exScale||f.engine||f.sacrifice||f.chooseExhaust||f.recoverExcluded||f.tokenSword||f.tokenKnife||f.exhaustStrength)a.push('exhaust');return a.length?a:axes.slice()}
 function roles(c){let f=c.fx||{};return {attack:!!(f.d||f.p||f.equalPoison||f.totalPoison||f.exactBlock),defense:!!(f.b||f.plate||f.agility||f.retainBlock||f.thorns),draw:!!(f.draw||f.recover||f.poisonDraw),heal:!!(f.heal||f.regen)}}
 function pick(c,deck,axis,weight=1){let f=c.fx||{},r=roles(c),n=Math.max(1,deck.length),counts={};for(const d of deck)for(const [k,v] of Object.entries(roles(d)))counts[k]=(counts[k]||0)+Number(v);const affinity=tags(c).includes(axis)?config.weights.axis*weight:0,key=(config.keys[axis]||[]).includes(c.id)?config.weights.key*weight:0;const efficiency=config.weights.efficiency*((f.d||0)*(f.h||1)/6+(f.b||0)/6+(f.p||0)*.8+(f.draw||0)*2+(f.s||0)*2+(f.agility||0)*2+(f.heal||0)/5+(f.plate||0)/3+(f.exactBlock||0)*6+(f.blockScale||0)*4+(f.s||0)*2+(f.exScale||0)*2+Number(!!(f.engine||f.burn||f.poisonDouble||f.retainBlock))*5)/(1+c.cost*.65);let role=0;for(const [k,v] of Object.entries(r))if(v)role+=Math.max(0,({attack:.4,defense:.35,draw:.15,heal:.08}[k])-((counts[k]||0)/n))*config.weights.role*4;const duplicate=-deck.filter(d=>d.id===c.id).length*.6-(f.hpLoss||0)*.7-(f.maxHpLoss||0)*1.2;return {axis:affinity,key,efficiency,role,duplicate,total:affinity+key+efficiency+role+duplicate}}
 function build(catalog,axis,weight){let deck=[],picks=[];const pool=catalog.filter(c=>!c.runOnly&&!c.retired);while(deck.length<config.deckSize){const role=deck.length<4?'defense':deck.length<8?'attack':deck.length<10?'heal':null;const offers=pool.filter(c=>deck.filter(d=>d.id===c.id).length<3&&(!role||roles(c)[role])&&(!c.fx.maxHpLoss||!deck.some(d=>d.fx.maxHpLoss))&&(!(c.fx.hpLoss||c.fx.maxHpLoss)||deck.filter(d=>d.fx.hpLoss||d.fx.maxHpLoss).length<2));const scores=offers.map(c=>({id:c.id,name:c.name,score:pick(c,deck,axis,weight)}));scores.sort((a,b)=>b.score.total-a.score.total||a.id-b.id);let chosen=scores[0];deck.push(pool.find(c=>c.id===chosen.id));picks.push({source:'base',offers:scores,selected:[chosen.id]})}return {deck:deck.map(c=>c.id),picks}}

 function incoming(o){return (o.enemies||[]).filter(e=>e.hp>e.poison).reduce((n,e)=>n+(String(e.intent).includes('attack')||String(e.intent).includes('攻撃')?e.attack*e.hits:0),0)}
 function score(a,o,axis,w=1){const c=(o.hand||[]).find((c,i)=>i===a.index&&a.type==='play')||(o.offers||[]).find(c=>c.id===a.cardId)||(o.deck||[]).find(c=>c.id===a.cardId);if(['reward','packSelect','chest'].includes(a.type))return c?pick(c,o.deck,axis,w).total-2:-2;
 if(a.type==='play'){const f=c.fx,e=o.enemies?.find(e=>e.index===a.enemy),alive=o.enemies.filter(e=>e.hp>0),inc=incoming(o),damage=(f.d!=null?Math.max(0,f.d+(o.strength||0)*(f.strScale||1))*(f.h||1):0)+(f.exactBlock?o.block*f.exactBlock+(o.strength||0):0)+(f.blockScale?o.block*f.blockScale:0)+(f.exScale?(o.excluded?.length||0)*f.exScale:0)+(f.equalPoison?(e?.poison||0):0)+(f.totalPoison?alive.reduce((s,e)=>s+e.poison,0):0);let val=damage*(f.all?alive.length:1)*.9;if(e&&damage>=e.hp+e.block)val+=12+e.attack*.5;val+=(f.p||0)*Math.max(1,5-o.turn*.3)*(f.all?alive.length:1);const b=Math.max(0,(f.b||0)+(f.b?o.guard:0))+(f.strengthBlock?o.strength:0);val+=Math.min(b,Math.max(0,inc-o.block))*1.6+Math.max(0,b-Math.max(0,inc-o.block))*.15+(f.plate||0)*1.7;
 val+=(f.s||0)*Math.max(2,8-o.turn)+(f.doubleStr?o.strength*5:0)+(f.agility||0)*3+(f.draw||0)*3+(f.energy||0)*6+Math.min(o.maxHp-o.hp,f.heal||0)*1.8+(f.regen||0)*2;
 val+=(f.poisonDouble?alive.reduce((s,e)=>s+e.poison,0)+8:0)+(f.retainBlock?8:0)+(f.burn?12:0)+(f.engine?9:0)+(f.exhaustStrength?12:0)+(f.heartbeat?8:0)+(f.forge?5:0)+(f.tokenSword?8:0)+(f.tokenKnife?6:0)+(f.recoverExcluded?5:0)+(f.chooseExhaust?5:0)+(f.sacrifice?4:0)+(f.thorns||0)*1.5+(f.passion?5:0);
 val-=(f.hpLoss||0)*(o.hp<20?4:1)+(f.maxHpLoss||0)*1.5;val+=tags(c).includes(axis)?w:0;if(axis==='block'&&b>0&&o.hand.some(x=>x.fx.exactBlock||x.fx.blockScale))val+=b*1.2;if(axis==='strength'&&f.s)val+=o.hand.filter(x=>x.fx.d).length*f.s*2;return val/(1+Math.max(0,c.cost)*.45);
 }
 if(a.type==='endTurn')return -1;
 if(a.type==='handChoice')return c?-pick(c,o.deck,axis,w).total:0;
 if(a.type==='recover')return c?pick(c,o.deck,axis,w).total:1;
 if(a.type==='node'){const t=o.map[a.row].find(n=>n.lane===a.lane).type;return ({rest:o.hp/o.maxHp<.65?20:0,elite:o.hp/o.maxHp>.8&&o.floor>3?7:-8,shop:o.gold>=40?10:-3,chest:15,mystery:3,fight:5,boss:1})[t]??0}
 if(a.type==='event'){const e=o.event.choices[a.index];return (e.card?7:0)+(e.max||0)*1.5+(e.gold||0)*.1+(e.hp>0?Math.min(o.maxHp-o.hp,e.hp)*1.5:(e.hp||0)*(o.hp<25?3:.6))-(e.cost||0)*.1}
 if(a.type==='buyPack'){let p=o.shop.packs[a.index];return p.id===axis?14:p.id==='epic'?8:2}
 if(a.type==='buyPotion')return o.hp<30?6:1;
 if(a.type==='potion'){const p=o.potions[a.index];if(p.id==='heal')return o.hp<=o.maxHp*.75?25:-100;if(o.mode!=='battle')return -100;return incoming(o)>o.block+o.hp*.25||o.floor===10?30:-50}
 if(a.type==='targetPotion')return 100-(o.enemies.find(e=>e.index===a.enemy)?.hp||0);
 if(a.type==='packFinish')return -2;return 0;
 }
 function choose(o,rng,axis,w){const ranked=o.actions.map(a=>({a,score:score(a,o,axis,w)})).sort((a,b)=>b.score-a.score);const best=ranked.filter(x=>Math.abs(x.score-ranked[0].score)<1e-8);return best[Math.floor(rng()*best.length)].a}
 globalThis.AI_POLICY={axes,names,config,tags,roles,pick,build,score,choose,incoming};
})();
